const errorKeys: Record<string, DiscordMessageKey> = {
  invalid_url: "errorInvalidUrl",
  confirmation_required: "errorConfirmationRequired",
  role_id_invalid: "errorRoleIdInvalid",
  role_id_required: "errorRoleIdRequired",
  destination_required: "errorDestinationRequired",
  notifications_disabled: "errorNotificationsDisabled",
  qualification_required: "errorQualificationRequired",
  locale_invalid: "errorLocaleInvalid",
  locale_not_ready: "errorLocaleNotReady",
};

export function discordText(locale: AppLocale, key: DiscordMessageKey, values: Record<string, string> = {}) {
  return Object.entries(values).reduce((result, [name, value]) => result.replaceAll(`{${name}}`, value), dictionaries[locale][key]);
}

export function discordErrorText(locale: AppLocale, error: unknown) {
  const match = String(error).match(/discord\.error\.([a-z_]+)/);
  return match ? discordText(locale, errorKeys[match[1]] ?? "commandFailed") : discordText(locale, "commandFailed");
}

export function allDiscordLocalesHaveCompleteMessages() {
  const expected = Object.keys(en).sort().join("|");
  return Object.values(dictionaries).every((dictionary) => Object.keys(dictionary).sort().join("|") === expected && Object.values(dictionary).every(Boolean));
}

export type { DiscordMessageKey };
